#!/usr/bin/env python3
"""From ECMA-376 presetShapeDefinitions.xml, write each preset's adjust values, the guides its
text rectangle depends on, and the rectangle, one preset per line (src/preset_text.txt):
  name|adj=fmla;...|guide=fmla;...|l t r b
Usage: make_preset_guides.py presetShapeDefinitions.xml > ../../src/preset_text.txt"""
import sys, xml.etree.ElementTree as ET
A = '{http://schemas.openxmlformats.org/drawingml/2006/main}'
root = ET.parse(sys.argv[1]).getroot()
print('# Generated by crates/geom/tests/fixtures/make_preset_guides.py from presetShapeDefinitions.xml.')
for sh in root:
    rect = sh.find(A + 'rect')
    if rect is None:
        continue
    av = [(g.get('name'), g.get('fmla')) for g in list(sh.find(A + 'avLst') if sh.find(A + 'avLst') is not None else [])]
    gds = [(g.get('name'), g.get('fmla')) for g in list(sh.find(A + 'gdLst') if sh.find(A + 'gdLst') is not None else [])]
    names = {n for n, _ in gds}
    need = set()
    todo = [rect.get(k) for k in 'ltrb']
    deps = dict(gds)
    while todo:
        x = todo.pop()
        if x in names and x not in need:
            need.add(x)
            todo += deps[x].split()[1:]
    kept = [(n, f) for n, f in gds if n in need]
    print('%s|%s|%s|%s' % (sh.tag, ';'.join(f'{n}={f}' for n, f in av), ';'.join(f'{n}={f}' for n, f in kept),
                           ' '.join(rect.get(k) for k in 'ltrb')))
